// Combinational circuit, time-independent (no $display calls, no $dumpfile).
// The function in the always @ (*) block determines the output Q for any given
// input A and B. The function is completely independent of the simulation
// time, so the register-based delay model (the $display calls) matches the
// combinational transfer function exactly.
module TopModule(input a, b, output q);
    always @ (*) begin
        q = a & b;
    end
endmodule

